mapper.select:
SELECT *
FROM (
         SELECT ROUND(port_in_count / 8 / 1024 / 1024, 2) AS value,
                COLLECT_TIME AS endTime
         FROM COLLECT_INTERFACES
         WHERE ASSET_ID = #{assetId}
           AND port_index = #{portName}
         ORDER BY COLLECT_TIME DESC
     )
WHERE rownum < 30

